@Component("allergy-handler")
@ProcessingGroup("allergy-processing-group")
public class AllergyEventHandler {
	
	// core constructor
	AllergyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAllergyEvent
     */
    @EventHandler
    public void handle( CreateAllergyEvent event) {
        entityManager.persist(new Allergy(event.getAllergyId(), event.getSubstance(), event.getReaction(), event.getPatient(), event.getSeverity(), event.getStatus()));
    }

    /*
     * @param	event UpdateAllergyEvent
     */
    @EventHandler
    public Allergy handle( UpdateAllergyEvent event) {
    	entityManager.merge(new Allergy(event.getAllergyId(), event.getSubstance(), event.getReaction(), event.getPatient(), event.getSeverity(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAllergyEvent
     */
    @EventHandler
    public void on( DeleteAllergyEvent event) {
    	Allergy entity = new Allergy();
   
    	// ------------------------------------------
    	// apply the AllergyId
    	// ------------------------------------------
    	entity.setAllergyId( event.getAllergyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AllergyRepository allergyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AllergyEventHandler.class.getName());

}
